        yield return Path.Combine(configHome, "opencode");

        var opencodeConfigDir = Environment.GetEnvironmentVariable("OPENCODE_CONFIG_DIR");
        if (!string.IsNullOrWhiteSpace(opencodeConfigDir))
        {
