            || name == CrossRuntimeReviewFiles.CopilotHome
            || name == CrossRuntimeReviewFiles.CopilotXdg
            || name == CrossRuntimeReviewFiles.OpencodeXdg
            || name == CrossRuntimeReviewFiles.OpencodeConfigDir)
