             {
                 if (!string.Equals(tokens[index + partIndex], parts[partIndex], StringComparison.Ordinal))
                 {
                     matched = false;
                     break;
                 }
             }

             if (matched)
             {
                 return true;
             }
         }

         return false;
     }
